// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;

    function setUp() public { c = new DepositLog(); }

    function testFuzz_property(address caller, bytes32 digest) public {
        vm.assume(caller != address(0));

        address requester = address(0x1234);
        uint256 utxoSize = 1;
        bytes memory redeemerOutputScript = hex"00";
        uint256 requestedFee = 0;
        bytes memory outpoint = hex"00";

        bool approved = c.approvedToLog(caller);

        bool ok;
        vm.prank(caller);
        try c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok == approved);
    }
}
